def run_agent(task, tools, max_turns=10):
    messages = [{"role": "user", "content": task}]
    for turn in range(max_turns):
        resp = client.messages.create(
            model=MODEL, max_tokens=4096, system=SYSTEM,
            tools=[t.schema for t in tools.values()],
            messages=messages)
        messages.append({"role": "assistant", "content": resp.content})
        if resp.stop_reason == "end_turn":
            return final_text(resp), messages
        if resp.stop_reason != "tool_use":
            raise StopError(resp.stop_reason)   # max_tokens, refusal...
        results = []
        for block in resp.content:
            if block.type != "tool_use":
                continue
            tool = tools.get(block.name)
            if tool is None:
                out, err = f"Unknown tool {block.name}", True
            elif not permitted(block.name, block.input):
                out, err = "Denied by user. Try another approach.", True
            else:
                try:
                    out, err = tool.run(**block.input), False
                except Exception as e:
                    out, err = f"{type(e).__name__}: {e}", True
            results.append({"type": "tool_result",
                            "tool_use_id": block.id,
                            "content": truncate(out, 8000),
                            "is_error": err})
        messages.append({"role": "user", "content": results})
    raise StopError("max_turns")

